script:
frappe.ui.form.on('Room Booking', {
    refresh: function(frm) {
        set_room_rate_filter(frm);
        add_sales_invoice_button(frm);
    },
    room: function(frm) {
        frm.set_value('room_rate', '');
        frm.set_value('rate_by_hour', 0);
        set_room_rate_filter(frm);
    },
    room_rate: update_rate,
    check_in: calculate_totals,
    check_out: calculate_totals,
});

frappe.ui.form.on('Room Booking Item', {
    item: fetch_item_rate,
    price_list: fetch_item_rate,
    qty: function(frm, cdt, cdn) {
        calculate_row_amount(cdt, cdn);
        calculate_items_amount(frm);
    },
    items_and_service_remove: function(frm) {
        calculate_items_amount(frm);
    }
});

function set_room_rate_filter(frm) {
    if (!frm.doc.room) {
        frm.set_query('room_rate', () => ({ filters: {} }));
        return;
    }

    frappe.db.get_value('Hotel Room', frm.doc.room, 'room_type').then(r => {
        const room_type = r.message.room_type;
        if (!room_type) return;

        frappe.db.get_list('Room Type Rate', {
            filters: { parent: room_type, enabled: 1 },
            fields: ['room_rate'],
            parent_doctype: 'Room Type',
            limit_page_length: 0
        }).then(rows => {
            const rate_names = rows.map(row => row.room_rate);
            frm.set_query('room_rate', () => ({
                filters: { name: ['in', rate_names] }
            }));
        });
    });
}

function update_rate(frm) {
    if (!frm.doc.room || !frm.doc.room_rate) return;

    frappe.db.get_value('Hotel Room', frm.doc.room, 'room_type').then(r => {
        const room_type = r.message.room_type;
        if (!room_type) return;

        frappe.db.get_list('Room Type Rate', {
            filters: {
                parent: room_type,
                room_rate: frm.doc.room_rate,
                enabled: 1
            },
            fields: ['rate_by_hour'],
            parent_doctype: 'Room Type',
            limit: 1
        }).then(rows => {
            if (rows.length) {
                frm.set_value('rate_by_hour', rows[0].rate_by_hour);
                calculate_totals(frm);
            } else {
                frappe.msgprint(__('Нет активного тарифа для этого типа номера'));
                frm.set_value('rate_by_hour', 0);
            }
        });
    });
}

function calculate_totals(frm) {
    if (!frm.doc.check_in || !frm.doc.check_out) return;

    const diff_hours = moment(frm.doc.check_out).diff(moment(frm.doc.check_in), 'hours', true);

    if (diff_hours <= 0) {
        frappe.msgprint(__('Check Out должен быть позже Check In'));
        frm.set_value('total_hours', 0);
        frm.set_value('amount', 0);
    } else {
        frm.set_value('total_hours', diff_hours);
        frm.set_value('amount', flt(frm.doc.rate_by_hour * diff_hours, precision('amount')));
    }
    calculate_total_amount(frm);
}

function fetch_item_rate(frm, cdt, cdn) {
    const row = locals[cdt][cdn];
    if (!row.item || !row.price_list) return;

    frappe.db.get_value('Item Price', {
        item_code: row.item,
        price_list: row.price_list
    }, 'price_list_rate').then(r => {
        const rate = (r.message && r.message.price_list_rate) || 0;
        frappe.model.set_value(cdt, cdn, 'rate', rate);
        if (!rate) {
            frappe.msgprint(__('Цена не найдена для этого товара в выбранном прайс-листе'));
        }
        calculate_row_amount(cdt, cdn);
        calculate_items_amount(frm);
    });
}

function calculate_row_amount(cdt, cdn) {
    const row = locals[cdt][cdn];
    frappe.model.set_value(cdt, cdn, 'amount', flt(row.rate) * flt(row.qty || 0));
}

function calculate_items_amount(frm) {
    let total = 0;
    (frm.doc.items_and_service || []).forEach(row => {
        total += flt(row.amount);
    });
    frm.set_value('items_and_serivce_amount', total);
    calculate_total_amount(frm);
}

function calculate_total_amount(frm) {
    frm.set_value('total_amount', flt(frm.doc.amount) + flt(frm.doc.items_and_serivce_amount));
}

function add_sales_invoice_button(frm) {
    if (frm.is_new() || frm.doc.pay_status === 'Paid') return;

    const label = frm.doc.sales_invoice
        ? __('Recreate Sales Invoice')
        : __('Create Sales Invoice');

    frm.add_custom_button(label, function () {
        const proceed = () => {
            frappe.call({
                method: 'make_sales_invoice_from_booking',
                args: { room_booking: frm.doc.name },
                freeze: true,
                freeze_message: __('Создание Sales Invoice...'),
                callback: function (r) {
                    if (r.message) {
                        frm.reload_doc();
                        frappe.set_route('Form', 'Sales Invoice', r.message);
                    }
                }
            });
        };

        if (frm.doc.sales_invoice) {
            frappe.confirm(
                __('Текущий Sales Invoice {0} будет отменён и создан новый. Продолжить?', [frm.doc.sales_invoice]),
                proceed
            );
        } else {
            proceed();
        }
    });
}
